$known = user_permission_get_modules();
$granted = $skipped = 0;
foreach ($prod as $rid => $permissions) {
  if (!user_role_load($rid)) {
    continue;
  }
  foreach ($permissions as $p) {
    list($permission, $module) = $p;
    if (!isset($known[$permission])) {
      $skipped++;
      continue;
    }
    db_merge('role_permission')->key(array('rid' => $rid, 'permission' => $permission))
      ->fields(array('module' => $known[$permission]))->execute();
    $granted++;
  }
}
cache_clear_all();
drush_print("Granted $granted production permissions ($skipped skipped: module not enabled).");
